export const ORIGINAL_FOOTPRINTS_ROLES = ["model", "observed", "conformance", "source", "tree"] as const;
export type OriginalFootprintsRole = typeof ORIGINAL_FOOTPRINTS_ROLES[number];
const modelOperations: readonly OriginalFootprintsOperation[] = ["log_model", "log_model_traces", "log_extensive", "trace_extensive", "precision", "fitness", "fitness_traces", "log_extensive_compare"];
const observedOperations: readonly OriginalFootprintsOperation[] = [...modelOperations, "flatten", "project", "relation_configurations"];
const vectorObservedOperations: readonly OriginalFootprintsOperation[] = ["log_model_traces", "trace_extensive", "fitness_traces", "flatten"];
const suppliedOperations: readonly OriginalFootprintsOperation[] = ["fitness", "fitness_traces", "diagnostics_log_model", "diagnostics_trace_extensive", "finalize_extensive", "flatten_conformance", "relation_activities", "tree_decorations", "tree_decorations_extensive"];
export const originalFootprintsCanIncludeDiagnostics = (operation: OriginalFootprintsOperation): boolean => operation === "log_model_traces" || operation === "trace_extensive";
export const originalFootprintsCanIncludeMetrics = (operation: OriginalFootprintsOperation): boolean => ["log_extensive", "trace_extensive", "log_extensive_compare"].includes(operation);
export const originalFootprintsUsesObserved = (operation: OriginalFootprintsOperation): boolean => observedOperations.includes(operation);
export const originalFootprintsObservedVector = (operation: OriginalFootprintsOperation): boolean => vectorObservedOperations.includes(operation);
export const originalFootprintsStandaloneDiagnostics = (operation: OriginalFootprintsOperation): boolean => operation === "diagnostics_log_model" || operation === "diagnostics_trace_extensive";
export interface OriginalFootprintsForm {operation: OriginalFootprintsOperation; observedMode: "exact" | "source"; sourceFormat: "import" | "raw_log"; treeFormat: "auto" | "ptml" | "tree_json"; discoveryVariant: "entire_event_log" | "trace_by_trace" | "entire_dataframe" | "polars_lazyframes"; inputFormat: MiningInputFormat; inputShape: MiningInputShape; selectors: Partial<Record<MiningSourceSelector, string>>; suppliedSelectors: Partial<Record<MiningSourceSelector, boolean>>; importFields: Record<string, string>; optionsJson: Record<OriginalFootprintsOptionGroup, string>; includeDiagnostics: boolean; includeMetrics: boolean;}
export const defaultOriginalFootprintsForm = (operation: OriginalFootprintsOperation = "log_model"): OriginalFootprintsForm => ({operation, observedMode: "exact", sourceFormat: "import", treeFormat: "auto", discoveryVariant: originalFootprintsObservedVector(operation) ? "trace_by_trace" : "entire_event_log", inputFormat: "auto", inputShape: "log", selectors: {}, suppliedSelectors: {}, importFields: {}, optionsJson: {log_model: "{}", trace_extensive: "{}", diagnostics: "{}", log_extensive_compare: "{}", discovery: "{}"}, includeDiagnostics: false, includeMetrics: false});
