  if (form.includeDiagnostics && !originalFootprintsCanIncludeDiagnostics(form.operation)) throw new Error("Auxiliary diagnostics applies only to tracewise comparison operations.");
  if (form.includeMetrics && !originalFootprintsCanIncludeMetrics(form.operation)) throw new Error("Auxiliary metrics applies only to extensive comparison operations.");
  const fields: Array<[string, string]> = [["operation", form.operation]], roles = originalFootprintsRoles(form);
  if (originalFootprintsUsesObserved(form.operation)) fields.push(["observed_mode", form.observedMode]);
  if (originalFootprintsCanIncludeDiagnostics(form.operation)) fields.push(["include_diagnostics", String(form.includeDiagnostics)]);
  if (originalFootprintsCanIncludeMetrics(form.operation)) fields.push(["include_metrics", String(form.includeMetrics)]);
